
import React, { useState, useEffect, useMemo, useRef } from "react";
import { createRoot } from "react-dom/client";
import { MapPin, Search, X, Plus, Star, Phone, Mail, Camera, Calendar, ChevronRight, Check, Radio, Crosshair, Navigation, Globe, Clock, Sparkles, Loader2, Instagram, Newspaper, ExternalLink, BadgeCheck, RotateCcw, Maximize2, Pencil, Download, Upload, AlertTriangle, Trash2, Settings } from "lucide-react";
// ---------- Geo helpers (stylized/schematic outline, not survey-accurate) ----------
const BOUNDS = { minLat: 47.2, maxLat: 55.0, minLng: 5.9, maxLng: 15.1 };
const VB = { w: 500, h: 700, pad: 10, innerW: 480, innerH: 680 };
const project = (lat, lng) => {
  const x = ((lng - BOUNDS.minLng) / (BOUNDS.maxLng - BOUNDS.minLng)) * VB.innerW + VB.pad;
  const y = ((BOUNDS.maxLat - lat) / (BOUNDS.maxLat - BOUNDS.minLat)) * VB.innerH + VB.pad;
  return [x, y];
};
const unproject = (x, y) => {
  const lng = ((x - VB.pad) / VB.innerW) * (BOUNDS.maxLng - BOUNDS.minLng) + BOUNDS.minLng;
  const lat = BOUNDS.maxLat - ((y - VB.pad) / VB.innerH) * (BOUNDS.maxLat - BOUNDS.minLat);
  return [lat, lng];
};
const KM_PER_PIXEL_Y = ((BOUNDS.maxLat - BOUNDS.minLat) * 111) / VB.innerH;
const haversineKm = ([lat1, lng1], [lat2, lng2]) => {
  const R = 6371;
  const dLat = ((lat2 - lat1) * Math.PI) / 180;
  const dLng = ((lng2 - lng1) * Math.PI) / 180;
  const a = Math.sin(dLat / 2) ** 2 + Math.cos((lat1 * Math.PI) / 180) * Math.cos((lat2 * Math.PI) / 180) * Math.sin(dLng / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
};

// Grobe Faustformel-Schätzung (Luftlinie -> Straßen-/Bahn-Umwegfaktor).
// Keine Live-Verkehrsdaten — für echte Zeiten verlinken wir auf Google Maps.
const estimateCarMinutes = (km) => {
  const roadKm = km * 1.25; // Umwegfaktor Straße
  const avgSpeed = km > 60 ? 100 : km > 20 ? 70 : 40; // Autobahn vs. Land-/Stadtstraße
  return Math.round((roadKm / avgSpeed) * 60 + 8);
};
const estimateTransitMinutes = (km) => {
  const railKm = km * 1.15;
  const avgSpeed = km > 150 ? 140 : km > 40 ? 90 : 35;
  return Math.round((railKm / avgSpeed) * 60 + 25); // + Umstiege/Wartezeit
};
const formatMinutes = (min) => {
  const h = Math.floor(min / 60), m = Math.round(min % 60);
  return h > 0 ? `${h} Std ${m} Min` : `${m} Min`;
};
const googleMapsUrl = ([oLat, oLng], [dLat, dLng], mode) =>
  `https://www.google.com/maps/dir/?api=1&origin=${oLat},${oLng}&destination=${dLat},${dLng}&travelmode=${mode}`;

// Schneidet alles ab dem ersten "?", "&" oder Zeilenumbruch in einer
// E-Mail-Adresse ab, bevor sie in einen mailto:-Link eingesetzt wird. Das
// verhindert, dass ein präpariertes E-Mail-Feld (z.B. "x@y.de?bcc=...")
// zusätzliche mailto-Parameter einschleust, ohne (anders als eine komplette
// encodeURIComponent()-Kodierung) das "@" zu verändern - dadurch bleibt die
// Adresse für E-Mail-Programme normal lesbar.
const sanitizeMailtoAddress = (email) => (email || "").split(/[?&\r\n]/)[0].trim();
const openMailto = (url) => {
  const a = document.createElement("a");
  a.href = url; a.target = "_blank";
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
};
const buildBookingMailto = (photographer, job) => {
  const dateRange = job.endDate && job.endDate !== job.date ? `${job.date} – ${job.endDate}` : job.date;
  const subject = `BILD Fotoredaktion – Anfrage: ${job.title}${job.date ? ` (${dateRange})` : ""}`;
  const body = [
    `Hallo ${photographer.name},`, "",
    "wir würden dich gerne für folgenden Termin buchen:", "",
    `Auftrag: ${job.title}`,
    `Ort: ${job.city}`,
    `Datum: ${job.date ? dateRange : "noch offen"}${job.zeit ? `, ${job.zeit} Uhr` : ""}`,
    `Thema: ${job.theme}`,
    job.redakteur ? `Redakteur:in/Reporter:in (Ansprechpartner:in): ${job.redakteur}${job.redakteurTelefon ? `, Tel. ${job.redakteurTelefon}` : ""}` : null,
    job.redaktion ? `Redaktion: ${job.redaktion}` : null,
    job.ressort ? `Ressort: ${job.ressort}` : null,
    "",
    "Bitte gib uns kurz Bescheid, ob der Termin für dich passt.", "",
    "Viele Grüße", "BILD Fotoredaktion",
  ].filter((l) => l !== null).join("\n");
  // encodeURIComponent auch auf die Empfänger-Adresse: verhindert, dass ein
  // präpariertes E-Mail-Feld (z.B. "...@x.de?bcc=angreifer@...") zusätzliche
  // mailto-Parameter wie bcc einschleusen und Buchungsmails heimlich
  // mitgelesen werden könnten.
  return `mailto:${sanitizeMailtoAddress(photographer.email)}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
};

