function ThemePill({ theme, active, onClick }) {
  const c = themeColor(theme);
  return (
    <button onClick={onClick} className="px-3 py-1.5 rounded-md border-2 text-[12px] font-semibold tracking-wide transition-all"
      style={{ fontFamily: "'Oswald', sans-serif", borderColor: c, background: active ? c : "transparent", color: active ? "#14161A" : c }}>
      {theme}
    </button>
  );
}

function TravelTimes({ origin, destination }) {
  const km = haversineKm(origin, destination);
  const car = estimateCarMinutes(km);
  const transit = estimateTransitMinutes(km);
  return (
    <div className="border border-[#3A3F4B] rounded-sm overflow-hidden mb-4">
      <div className="px-2.5 py-1.5 bg-[#22252C] text-[10px] uppercase tracking-wide text-[#5B6472] flex items-center justify-between">
        <span>Geschätzte Fahrzeit zum Termin</span>
        <span>{km.toFixed(0)} km Luftlinie</span>
      </div>
      <a href={googleMapsUrl(origin, destination, "driving")} target="_blank" rel="noopener noreferrer"
        className="flex items-center justify-between px-2.5 py-2 border-t border-[#2A2E37] hover:bg-[#22252C] text-sm">
        <span className="flex items-center gap-2">🚗 Auto</span>
        <span className="flex items-center gap-1.5 text-[#C7CCD6]">~{formatMinutes(car)} <ChevronRight size={13} className="text-[#5B6472]"/></span>
      </a>
      <a href={googleMapsUrl(origin, destination, "transit")} target="_blank" rel="noopener noreferrer"
        className="flex items-center justify-between px-2.5 py-2 border-t border-[#2A2E37] hover:bg-[#22252C] text-sm">
        <span className="flex items-center gap-2">🚆 ÖPNV</span>
        <span className="flex items-center gap-1.5 text-[#C7CCD6]">~{formatMinutes(transit)} <ChevronRight size={13} className="text-[#5B6472]"/></span>
      </a>
      <div className="px-2.5 py-1.5 text-[9px] text-[#5B6472] border-t border-[#2A2E37]" style={{fontFamily:"'IBM Plex Mono', monospace"}}>
        Faustformel-Schätzung, keine Live-Verkehrsdaten · Klick öffnet echte Route in Google Maps
      </div>
    </div>
  );
}

function TagChip({ label, active, onClick, color }) {
  if (color) {
    return (
      <button onClick={onClick} className="px-2.5 py-1 rounded-sm border text-[11px] tracking-wide uppercase font-medium transition-colors"
        style={{ fontFamily: "'IBM Plex Mono', monospace", borderColor: color, background: active ? color : "transparent", color: active ? "#14161A" : color }}>
        {label}
      </button>
    );
  }
  return (
    <button onClick={onClick} className={`px-2.5 py-1 rounded-sm border text-[11px] tracking-wide uppercase font-medium transition-colors ${active ? "bg-[#E0332F] text-white border-[#E0332F]" : "bg-transparent text-[#C7CCD6] border-[#3A3F4B] hover:border-[#E0332F]"}`} style={{fontFamily:"'IBM Plex Mono', monospace"}}>
      {label}
    </button>
  );
}

function TagInput({ value, onChange, suggestions }) {
  const [draft, setDraft] = useState("");
  const add = (tag) => { const t = tag.trim(); if (t && !value.includes(t)) onChange([...value, t]); setDraft(""); };
  return (
    <div>
      <div className="flex flex-wrap gap-1.5 mb-2">
        {value.map((t) => (
          <span key={t} className="flex items-center gap-1 px-2 py-0.5 bg-[#2A2E37] border border-[#3A3F4B] text-[#E8B563] text-[11px] uppercase tracking-wide" style={{fontFamily:"'IBM Plex Mono', monospace"}}>
            {t}<X size={11} className="cursor-pointer hover:text-white" onClick={() => onChange(value.filter((x) => x !== t))} />
          </span>
        ))}
      </div>
      <input value={draft} onChange={(e) => setDraft(e.target.value)}
        onKeyDown={(e) => { if (e.key === "Enter" || e.key === ",") { e.preventDefault(); add(draft); } }}
        placeholder="Label eingeben + Enter …"
        className="w-full bg-[#1B1D22] border border-[#3A3F4B] rounded-sm px-2 py-1.5 text-sm text-[#F5F3EE] placeholder-[#5B6472] focus:outline-none focus:border-[#E0332F]" />
      <div className="flex flex-wrap gap-1 mt-2">
        {suggestions.filter((s) => !value.includes(s)).slice(0, 8).map((s) => (
          <button key={s} onClick={() => add(s)} className="text-[10px] px-1.5 py-0.5 border border-dashed border-[#3A3F4B] text-[#5B6472] hover:text-[#E8B563] hover:border-[#E8B563]" style={{fontFamily:"'IBM Plex Mono', monospace"}}>+{s}</button>
        ))}
      </div>
    </div>
  );
}

